mapper.update:
update users set
  points=#{points}
where userid=#{user_id}

update product_detail set
  stock_qty=stock_qty+#{stock_qty}

  where product_id=#{product_id} and stock_qty+#{stock_qty}>=0

update orders_item set
  order_status=#{order_status}
where order_item_id=#{order_item_id}

update delivery set
  delivery_status=#{delivery_status}
where order_item_id=#{order_item_id}

mapper.select:
select NVL(SUM(line_total_amount), 0) AS total_canceled from (
  select line_total_amount from orders_item where order_id=#{order_id} and order_item_id in (
    select order_item_id from orders_canceled
  )
)
